PVD("vanuatu_sector_vu-national-ict-policy",{"docs":["","VU National ICT Policy"],"s":{"1":[[1,"3","2","ICT access expansion in schools and public services (also read at p.3 §4; p.13 §4; p.21 §6; p.13 §3; p.13 §5; p.26 §3; p.26 §4; p.22 §3; p.46 §4; p.46 §5; p.47 §2; p.47 §3; p.24 §4; p.24 §7; p.43 §7; p.47 §4; p.44 §2; p.44 §3; p.45 §2)","Access to ICTs in schools in particular, and also for Vanuatu citizens and residents in general, will be radically expanded.",""]],"2":[[1,"3","3","ICT risk preparedness, education and awareness programme (also read at p.22 §1; p.14 §4; p.12 §5; p.23 §4; p.24 §6; p.25 §7; p.26 §5; p.34 §4; p.33 §7; p.34 §3)","ensuring that those dangers are properly addressed and managed, in particular through appropriate preparedness, education and awareness building.",""]],"3":[[1,"6","2","National ICT policy coordination, implementation, monitoring and review framework (also read at p.7 §4; p.7 §6; p.7 §7; p.11 §5; p.11 §6; p.42 §4; p.47 §8; p.49 §4; p.49 §5; p.49 §6)","This document will serve as a tool for an eﬀective coordination of eﬀorts of all of the various stakeholders",""]],"4":[[1,"12","4","Strengthening of the telecommunications regulator (also read at p.35 §2; p.36 §3; p.36 §5; p.36 §6; p.37 §2; p.38 §7; p.47 §6)","a strong, competent and independent regulator—the Telecommunications and Radiocommunications Regulator (TRR)",""]],"5":[[1,"12","7","Telecommunications and electronic transactions legal framework (also read at p.13 §2; p.13 §2; p.13 §2)","Laws governing the telecommunications sector",""]],"6":[[1,"13","6","School-based community ICT learning centres (also read at p.43 §4)","schools are well placed to serve community needs for access to ICTs by becoming Community Learning, Information and Communication Centres.",""]],"7":[[1,"14","2","ICT-enabled financial and service transactions (also read at p.14 §2)","Internet banking is available to residents and businesses",""]],"8":[[1,"26","7","End-to-end ICT infrastructure planning and bottleneck resolution (also read at p.39 §7)","the Government will take an end-to-end network approach",""]],"9":[[1,"27","8","Shared ICT access facilities and community access points (also read at p.28 §8)","shared access to ICTs, including via use of ICTs in shared (common) facilities",""]],"10":[[1,"31","3","Private sector enablement for ICT market expansion (also read at p.32 §4; p.34 §5)","enable the private sector to take over and serve the expanded market",""]],"11":[[1,"32","6","Transparent and non-discriminatory ICT business environment reform (also read at p.32 §6)","further improve such transparency and predictability",""]],"12":[[1,"33","3","Private investment attraction for the ICT sector","policies aimed at attracting such investments and investor-targeting",""]],"13":[[1,"33","4","Transparent management of public ICT resources","publicly or centrally controlled resources",""]],"14":[[1,"33","5","Universal access policy for telecommunications expansion (also read at p.41 §5; p.41 §5)","an appropriate Universal Access Policy (UAP), especially the one formulated along the “pay or play” principles",""]],"15":[[1,"36","4","Support for judicial review of ICT regulatory decisions","independent, eﬃcient and swift judicial review of regulatory decisions",""]],"16":[[1,"38","4","Review of ICT and related sector regulatory structure","intends to review the current regulatory structure for ICT and related sectors",""]],"17":[[1,"38","5","Arm's-length and competitively neutral governance of government ICT market activities (also read at p.40 §5)","it will aim to do so at a sufficient “arm’s length”",""]],"18":[[1,"38","6","Transparency and conflict-of-interest safeguards in ICT governance","appropriate safeguards to ensure that potential conﬂicts of interest would be avoided",""]],"19":[[1,"39","4","Demand-side preference for ICT access interventions (also read at p.39 §5)","the Government will normally prefer demand-side interventions",""]],"20":[[1,"40","3","Government network sharing and reciprocal resilience arrangements (also read at p.40 §4; p.40 §4)","exchanging redundant links to enhance resiliency of telecommunications networks",""]],"21":[[1,"40","7","Transparent subsidies and procurement instruments for ICT market development (also read at p.41 §3; p.41 §4; p.43 §3; p.43 §5)","the Government may decide to subsidise the development of the market",""]],"22":[[1,"42","3","Regionalisation and internationalisation of ICT markets (also read at p.49 §3)","apply the same approach in relation to regionalisation and internationalisation of ICT markets",""]],"23":[[1,"42","6","Anchor tenant approach for remote ICT infrastructure sharing","an “anchor tenant” approach",""]],"24":[[1,"45","5","Supportive environment for line and local ICT stakeholders","peer-support networks",""]],"25":[[1,"45","6","Adaptive ICT policy design and learning system (also read at p.46 §3)","systems and processes that would ensure constant adaptability of the Policy",""]],"26":[[1,"48","4","Inclusive and universally designed ICT accessibility promotion","promote availability and use of universally designed ICT-related goods, services, equipment and facilities",""]],"27":[[1,"51","5","National ICT implementation planning (also read at p.52 §2; p.57 §4; p.57 §12)","Implementation plan, which will be based on the consolidated list of strategies",""]],"28":[[1,"52","4","ICT Development Fund establishment and enhancement (also read at p.71 §4)","ICT Development Fund, which will primarily be used to provide seed funding for initiatives covered by this Policy",""]],"29":[[1,"52","5","ICT partnership and funding mobilization","Support of development partners as well as international and regional organisations will be sought to fund the implementation of this Policy.",""]],"30":[[1,"52","6","ICT programme coordination and facilitation","the Government will encourage and facilitate coordination of such design and implementation with activities under this Policy",""]],"31":[[1,"53","2","ICT policy monitoring and annual reporting (also read at p.53 §3)","The National ICT Development Committee shall prepare and submit to the Council of Ministers an annual report on the implementation of this Policy",""]],"32":[[1,"53","4","ICT policy awareness and stakeholder engagement (also read at p.71 §8)","will seek to ensure that international and local stakeholders, as well as the public at large, are well aware of this Policy",""]],"33":[[1,"53","5","Legal and administrative instruments for ICT policy implementation","supported by appropriate legislation, decisions of the Council of Ministers, Memoranda of Understanding and other appropriate instruments",""]],"34":[[1,"53","6","National ICT policy review and revision","the Government will aim to review and, where appropriate, revise this Policy within 5 years from its adoption.",""]],"35":[[1,"54","3","School ICT connectivity grant programme (also read at p.55 §2; p.63 §2; p.63 §3; p.55 §3; p.63 §4)","via an applications-based competitive contributory grant programme",""]],"36":[[1,"55","5","School-based community learning and ICT centres (also read at p.64 §10)","schools should become Community Learning, Information and Communication Centres",""]],"37":[[1,"56","5","ICT infrastructure deployment and access expansion","support, extend and strengthen deployment and operation of as well as provision of access to ICT infrastructure",""]],"38":[[1,"56","15","E-government service delivery expansion","Government services will be delivered in a much more effective, transparent and efficient way and will be made much more accessible",""]],"39":[[1,"57","2","Cross-government ICT spending target setting","develop an agreed-upon reasonable target percentage for spending on ICTs",""]],"40":[[1,"57","8","Critical infrastructure protection for ICT systems","protection of critical infrastructure specifically require attention of the Government",""]],"41":[[1,"58","3","Cybersecurity policy and legislation working group","The Government has already established the Cybersecurity Policy and Legislation Working Group.",""]],"42":[[1,"58","8","Development of digital content in Bislama and local languages (also read at p.69 §8)","kick-start the development of content in such languages",""]],"43":[[1,"58","12","Translation and digital publication of existing content in local languages (also read at p.58 §13; p.69 §6)","facilitating translation of existing content into Bislama and local languages",""]],"44":[[1,"59","11","Public servant ICT skills development (also read at p.69 §13)","Upgrading ICT and ICT-related skills of public servants",""]],"45":[[1,"59","12","Multi-stakeholder ICT sector development initiatives","enable a multiplicity of stakeholders to undertake initiatives aimed at developing the ICT sector",""]],"46":[[1,"60","3","National ICT Development Committee strengthening and sector working groups (also read at p.70 §2)","Continuing effective work and further development of the National ICT Development Committee and, where required, setting up sector/issue working groups",""]],"47":[[1,"64","2","Submarine cable deployment","at least one submarine cable",""]],"48":[[1,"64","3","International connectivity reliability enhancement","Exploring and facilitating implementation of options to enhance reliability of international connectivity",""]],"49":[[1,"64","4","Vanuatu Internet Exchange Point development","Further development of the Vanuatu Internet Exchange Point",""]],"50":[[1,"64","11","Public Internet Access Point grant programme","Increasing the number of sustainable cost-efficient Public Internet Access Points via an applications-based competitive contributory grant programme",""]],"51":[[1,"65","2","ICT public access support platform","setting up a peer support network and organising peer-support events",""]],"52":[[1,"65","3","Licensing framework adjustment for public Internet access and shared networks","Adjusting licensing framework to enable Public Internet Access Points and shared use of access to ICT services",""]],"53":[[1,"65","5","Radio spectrum allocation and assignment framework","Strategy and framework for allocation and assignment of radio spectrum",""]],"54":[[1,"65","10","Shared ICT infrastructure and services cost reduction policy","Promoting reduction of costs of ICT infrastructure and services through increased shared use",""]],"55":[[1,"66","2","Multi-stakeholder infrastructure development and utilisation group","Establishment of and support to a multi-stakeholder and multi-sector infrastructure development and utilisation group",""]],"56":[[1,"66","5","Customs duties and VAT policy for ICT goods and services","Policy and framework for application of customs duties and taxes, in particular VAT, for ICT-related goods and services",""]],"57":[[1,"66","7","Digital broadcasting support and spectrum reallocation","Support to Digital broadcasting, in terms of spectrum efficiency, higher video and audio quality and new business opportunities.",""]],"58":[[1,"67","7","ICT use for disaster management and climate adaptation","Utilising ICTs in disaster management and climate change mitigation and adaptation",""]],"59":[[1,"68","2","ICT business and investment attraction policy","Policy and strategy for attracting and supporting ICT-related and ICT-enabled businesses and investments",""]],"60":[[1,"68","8","ICT use for culture preservation and promotion","Policy and strategy for utilisation of ICTs to preserve and promote Vanuatu culture",""]],"61":[[1,"68","12","ICT demonstration models and policy support activities","Showcasing, piloting, and setting up demonstration models as well as supporting conferences and workshops",""]],"62":[[1,"69","2","Code of practice for online content","The focus of this Code should include family protection, scam protection, and should discourage mis-use and waste of ICT resources",""]],"63":[[1,"69","11","Working committee on information collection and dissemination standards","Establish a Working Committee on standards of collecting and dissemination of information",""]],"64":[[1,"70","4","ICT development support coordination platform","Setting up a platform, including inventory of initiatives, for the coordination of support from public and private partners for ICT development",""]],"65":[[1,"70","7","Review of institutional structure for ICT market regulation","Reviewing institutional structure for market regulation",""]],"66":[[1,"70","9","Business and consumer advisory group dialogue with telecommunications industry","enhancing a dialogue between those groups and the telecommunications industry",""]],"67":[[1,"70","13","Formalization of ICT sector governance structure","Formalising governance structure for the ICT sector",""]],"68":[[1,"70","14","Strengthening OGCIO implementation capacity","Ensuring that the OGCIO has capacity to implement its duties as per the National ICT Policy",""]],"69":[[1,"71","2","Memoranda of understanding for ICT policy implementation","Developing, entering into and implementing Memoranda of Understanding between the OGCIO and implementing Ministries and Government Departments",""]],"70":[[1,"71","7","Annual ICT sector awards","Annual awards for achievements in the ICT sector",""]],"71":[[1,"71","9","International and regional ICT sector coordination and collaboration","Strengthening international and regional coordination and collaboration in relation to the ICT sector development",""]]}});
